def find_separator(grid):
    """The index of a full one-color row, else of a full one-color column, else None."""
    for i, row in enumerate(grid):
        if len(set(row)) == 1:
            return ('row', i)
    for j in range(len(grid[0])):
        if len({row[j] for row in grid}) == 1:
            return ('col', j)
    return None

def overlap_halves(grid, color=2):
    """Split the grid at its one-color separator row/column; keep cells nonzero in both halves, recolored."""
    kind, s = find_separator(grid)
    if kind == 'row':
        A, B = grid[:s], grid[s+1:]
        return [[color if a and b else 0 for a, b in zip(ra, rb)] for ra, rb in zip(A, B)]
    A = [r[:s] for r in grid]; B = [r[s+1:] for r in grid]
    return [[color if a and b else 0 for a, b in zip(ra, rb)] for ra, rb in zip(A, B)]
'''
